-- Food items and their nutrient amounts (per 100g)
WITH ins AS (
    INSERT INTO food_item (name, category, serving_size_g)
    SELECT 'Sữa bò tươi', 'Sữa và sản phẩm chế biến', 100
    WHERE NOT EXISTS (SELECT 1 FROM food_item_tag WHERE tag = 'source:vdd:10001')
    RETURNING id
)
INSERT INTO food_item_tag (food_item_id, tag)
SELECT id, 'source:vdd:10001' FROM ins;
INSERT INTO food_item_nutrient (food_item_id, nutrient_id, amount_per_100g)
SELECT t.food_item_id, n.id, v.amount
FROM food_item_tag t
JOIN LATERAL unnest(ARRAY['protein', 'total-lipid-fat', 'carbohydrate-by-difference', 'retinol', 'vit-a-rae', 'carotene', 'vit-c', 'ca', 'fe', 'na', 'k', 'zn', 'water', 'tryptophan', 'threonine', 'isoleucine', 'leucine', 'lysine', 'methionine', 'cystine', 'phenylalanine', 'tyrosine', 'valine', 'arginine', 'histidine', 'alanine', 'aspartic-acid', 'glutamic-acid', 'glycine', 'proline', 'serine', 'fatty-acids-total-saturated', 'c16-0', 'c18-0', 'fatty-acids-total-monounsaturated', 'c18-1-c', 'fatty-acids-total-polyunsaturated', 'c-18-2-cis-n-6-linoleic-acid', 'c-18-3-cis-n-3-alpha-linolenic-acid', 'sugars-total', 'ash', 'mg', 'p', 'cu', 'mn', 'se', 'vit-d-d2-d3', 'vit-e', 'thiamin', 'riboflavin', 'niacin', 'pantothenic-acid', 'vit-b6', 'folate-total', 'folate-food', 'vit-k-phylloquinone', 'energy']::varchar[], ARRAY[3.9, 4.4, 4.8, 50, 51.83, 22, 1, 111.33, 0.09, 352.54, 132.67, 0.37, 86.2, 50, 190, 250, 460, 320, 90, 28, 180, 137, 240, 170, 100, 95, 221, 640, 57, 297, 167, 1.87, 0.83, 0.37, 0.81, 0.81, 0.2, 0.12, 0.08, 5.26, 0.7, 14.84, 88.14, 0.02, 0, 1.11, 1, 0.06, 0.05, 0.19, 0.1, 0.36, 0.04, 5, 5, 0.2, 74]::double precision[]) AS v(code, amount) ON true
