    SELECT 'Chả cá basa, rán', 'Thủy sản và sản phẩm chế biến', 100
    WHERE NOT EXISTS (SELECT 1 FROM food_item_tag WHERE tag = 'source:vdd:8064008')
    RETURNING id
)
INSERT INTO food_item_tag (food_item_id, tag)
SELECT id, 'source:vdd:8064008' FROM ins;
INSERT INTO food_item_nutrient (food_item_id, nutrient_id, amount_per_100g)
SELECT t.food_item_id, n.id, v.amount
FROM food_item_tag t
JOIN LATERAL unnest(ARRAY['protein', 'total-lipid-fat', 'carbohydrate-by-difference', 'vit-a-rae', 'carotene', 'ca', 'fe', 'zn', 'water', 'threonine', 'isoleucine', 'leucine', 'lysine', 'methionine', 'cystine', 'phenylalanine', 'tyrosine', 'valine', 'arginine', 'histidine', 'alanine', 'aspartic-acid', 'glutamic-acid', 'glycine', 'serine', 'ash', 'p', 'vit-e', 'thiamin', 'riboflavin', 'energy']::varchar[], ARRAY[11.1, 13, 6.12, 0.3, 0.3, 75.7, 0.6, 0.44, 67.8, 0.57, 0.27, 0.56, 0.54, 0.2, 0.17, 0.34, 0.27, 0.28, 0.46, 0.89, 0.15, 0.7, 0.49, 0.08, 0.8, 1.98, 506.8, 28.89, 0.06, 0, 186]::double precision[]) AS v(code, amount) ON true
JOIN nutrient n ON n.code = v.code
WHERE t.tag = 'source:vdd:8064008'
ON CONFLICT (food_item_id, nutrient_id) DO UPDATE SET amount_per_100g = EXCLUDED.amount_per_100g;

